mapper.select:
SELECT c.*, d.title, d.external_ref, d.document_number, d.issuing_authority, d.publish_date, d.validity_status,
1.0 - (e.embedding::vector(768) <=> #{embedding, typeHandler=com.kma.knowledge.config.PgvectorTypeHandler}) AS retrieval_score
1.0 - (e.embedding::vector(1536) <=> #{embedding, typeHandler=com.kma.knowledge.config.PgvectorTypeHandler}) AS retrieval_score
1.0 - (e.embedding::vector(1024) <=> #{embedding, typeHandler=com.kma.knowledge.config.PgvectorTypeHandler}) AS retrieval_score
FROM knowledge_chunk c JOIN knowledge_doc d ON c.doc_id = d.doc_id JOIN knowledge_chunk_embedding e ON e.chunk_id = c.chunk_id AND e.active = TRUE WHERE c.space_id = #{spaceId} AND d.is_active = TRUE AND e.dimension = #{dimension}
AND e.profile_code = #{profileCode}
AND c.source_tag IN
#{tag}
AND d.publication_managed = TRUE AND d.workflow_status = 'published' AND d.online = TRUE AND (d.validity_status <> 'effective' OR ((d.effective_date IS NULL OR d.effective_date <= CURRENT_DATE) AND (d.expiry_date IS NULL OR d.expiry_date >= CURRENT_DATE)))
AND d.content_type IN #{value}
AND d.validity_status IN #{value}
AND d.doc_id = #{filters.docId}
AND EXISTS (SELECT 1 FROM knowledge_doc_topic dt JOIN knowledge_topic t ON t.topic_id=dt.topic_id WHERE dt.doc_id=d.doc_id AND t.topic_code IN #{value})
ORDER BY retrieval_score DESC LIMIT #{limit}

SELECT c.*, d.title, d.external_ref, d.document_number, d.issuing_authority, d.publish_date, d.validity_status, ts_rank_cd(c.search_vector, to_tsquery('simple', #{query})) AS retrieval_score FROM knowledge_chunk c JOIN knowledge_doc d ON c.doc_id = d.doc_id WHERE c.space_id = #{spaceId} AND d.is_active = TRUE AND c.search_vector @@ to_tsquery('simple', #{query})
AND c.source_tag IN
#{tag}
AND d.publication_managed = TRUE AND d.workflow_status = 'published' AND d.online = TRUE AND (d.validity_status <> 'effective' OR ((d.effective_date IS NULL OR d.effective_date <= CURRENT_DATE) AND (d.expiry_date IS NULL OR d.expiry_date >= CURRENT_DATE)))
AND d.content_type IN #{value}
AND d.validity_status IN #{value}
AND d.doc_id = #{filters.docId}
AND EXISTS (SELECT 1 FROM knowledge_doc_topic dt JOIN knowledge_topic t ON t.topic_id=dt.topic_id WHERE dt.doc_id=d.doc_id AND t.topic_code IN #{value})
ORDER BY retrieval_score DESC LIMIT #{limit}
